#!/usr/bin/env python3
"""Proof verification: Fundamental Theorem of Calculus (Part 1). Every step machine-checked."""
import math
def F(x, f, a=0.0, n=20000):
    h = (x-a)/n
    return sum(f(a + (i+0.5)*h) for i in range(n))*h
for f, name in [(lambda t: t*t, "t^2"), (math.sin, "sin"), (lambda t: math.e**t, "e^t")]:
    for x in (0.5, 1.0, 2.0):
        h = 1e-5
        dF = (F(x+h, f) - F(x-h, f)) / (2*h)
        assert abs(dF - f(x)) < 1e-3, "FTC failed for " + name
print("FTC Part 1 verified numerically: d/dx[int_a^x f] = f(x) for t^2, sin, e^t")

#!/usr/bin/env python3
"""Proof verification: Limit of sin(x)/x. Every step machine-checked."""
import math
# verify the squeeze inequalities numerically near 0
for x in [0.5, 0.1, 0.01, 0.001, -0.1, -0.01]:
    if x > 0:
        assert math.sin(x) < x < math.tan(x), "squeeze inequality failed"
    assert math.cos(x) < math.sin(x)/x < 1 or abs(x) < 1e-9
for x in [0.1, 0.01, 0.001, 1e-4]:
    assert abs(math.sin(x)/x - 1) < x, "limit not approached"
print("squeeze inequalities verified; sin(x)/x -> 1 confirmed numerically")
